import { forwardRef, useEffect, useRef, useState, type ElementType, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { useFocusTrap } from "@/hooks/use-focus-trap";

export interface MobileNavItem {
  /** Stable key for React lists. */
  key: string;
  label: string;
  active?: boolean;
  /** Router target -- rendered via `linkComponent` (or a plain `<a href>`). */
  to?: string;
  /**
   * Click handler. Rendered as a `<button>` when there is no `to`; also fired
   * on selection of a `to` item (e.g. to run side effects alongside nav).
   */
  onClick?: () => void;
  /**
   * Renders the item's icon at the given px size; `active` lets the caller
   * switch weight/fill. Called for both the bottom bar (size 24, stacked) and
   * the overflow menu (size 20, inline), so the DS stays icon-library-agnostic.
   */
  renderIcon: (opts: { active: boolean; size: number }) => ReactNode;
}

export interface MobileBottomNavProps {
  navItems: MobileNavItem[];
  /**
   * Toolbar pill (e.g. an `ActionPill`) nested to the right of the nav items.
   * Optional -- omit it for a nav that has no toolbar actions.
   */
  toolbar?: ReactNode;
  /**
   * Worst-case copy of the toolbar -- every action visible -- used ONLY for the
   * overflow measurement. Toolbar contents can change per page (1 action on one
   * page, 3 on another); measuring the widest case keeps the collapse decision
   * stable so the nav doesn't flip between inline and hamburger as you navigate.
   * Falls back to `toolbar` when omitted.
   */
  measureToolbar?: ReactNode;
  /** Hamburger icon for the collapsed state (e.g. a Phosphor `<List size={24} />`). */
  menuIcon: ReactNode;
  /** Label under the collapsed hamburger + its aria-label (caller-translated). */
  menuLabel?: string;
  /**
   * Router `Link` component for `to` items (e.g. react-router's `Link`), so the
   * DS needn't depend on a router. Falls back to a plain `<a href>`.
   */
  linkComponent?: ElementType;
  className?: string;
}

// Frosted pill chrome -- mirrors the `BottomNav` inner pill.
const PILL =
  "flex items-center gap-1 h-16 px-2 rounded-full backdrop-blur-[16px] shadow-lg " +
  "bg-[color-mix(in_srgb,var(--color-surface-light)_80%,transparent)] " +
  "dark:bg-[color-mix(in_srgb,var(--color-surface-dark)_80%,transparent)] " +
  "border border-[var(--color-border-light)] dark:border-[var(--color-border-dark)]";

// Bottom-bar item: stacked icon over label (the `BottomNavItem` style).
const BAR_ITEM =
  "wj-focus-ring flex flex-col items-center justify-center px-4 py-2 rounded-xl transition-colors touch-target";

// Menu row: inline icon beside label (matches an app's desktop header nav links).
const MENU_ITEM =
  "wj-focus-ring flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium transition-colors w-full";

function itemColor(active: boolean): string {
  return active
    ? "text-[var(--color-warm-800)] dark:text-white"
    : "text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)]";
}

function menuItemColor(active: boolean): string {
  return active
    ? "bg-[var(--color-warm-100)] text-[var(--color-warm-700)] dark:bg-[var(--color-neutral-800)] dark:text-white"
    : "text-[var(--color-text-secondary-light)] dark:text-[var(--color-text-secondary-dark)] hover:bg-[var(--color-warm-50)] dark:hover:bg-[var(--color-neutral-800)]";
}

/**
 * Mobile bottom navigation that consolidates its nav items into a hamburger
 * menu when they would overflow the viewport width.
 *
 * Layout: a single frosted pill holding the nav items with the `toolbar` pill
 * nested to their right. When the worst-case content (all nav items + every
 * toolbar action) would exceed the available width -- measured via a hidden,
 * always-expanded copy + a `ResizeObserver` -- the nav items collapse to a
 * single hamburger button; tapping it opens a frosted menu above the bar that
 * lists the items inline. Measuring the worst case (not the current page's
 * toolbar) keeps the decision stable: it's the hamburger on every page or
 * inline on every page, never flipping as you navigate. Mobile-only
 * (`md:hidden`); pair with a desktop header nav.
 */
export const MobileBottomNav = forwardRef<HTMLDivElement, MobileBottomNavProps>(function MobileBottomNav({
  navItems,
  toolbar,
  measureToolbar,
  menuIcon,
  menuLabel = "Menu",
  linkComponent: LinkComponent,
  className,
}, ref) {
  const [overflow, setOverflow] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const measureRef = useRef<HTMLDivElement>(null);
  // Menu container -- focus trap target.
  const menuRef = useRef<HTMLDivElement>(null);

  // Trap focus inside the overflow menu while it's open; restores hamburger focus on close.
  useFocusTrap(menuRef, overflow && menuOpen);

  // Escape closes the menu (focus trap handles Tab containment).
  useEffect(() => {
    if (!menuOpen) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") setMenuOpen(false);
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [menuOpen]);

  // Collapse when the worst-case content is wider than the available row. The
  // hidden measure copy is always expanded (all nav items + the full toolbar),
  // so the decision never flip-flops with the collapsed state OR with the
  // current page's toolbar. Re-runs on container OR content resize (the latter
  // covers label/locale width changes).
  useEffect(() => {
    const container = containerRef.current;
    const measure = measureRef.current;
    if (!container || !measure) return;
    const check = () => setOverflow(measure.scrollWidth > container.clientWidth + 1);
    check();
    const ro = new ResizeObserver(check);
    ro.observe(container);
    ro.observe(measure);
    return () => ro.disconnect();
  }, []);

  // Close the menu if we grow back to fitting inline.
  useEffect(() => {
    if (!overflow) setMenuOpen(false);
  }, [overflow]);

  const renderNavEl = (
    item: MobileNavItem,
    classes: string,
    onClick: (() => void) | undefined,
    children: ReactNode,
    role?: string,
  ) => {
    const props = {
      className: classes,
      onClick,
      ...(role ? { role } : {}),
      // Expose the active page to assistive tech, not just visually.
      ...(item.active && item.to ? { "aria-current": "page" as const } : {}),
    };
    if (item.to) {
      if (LinkComponent) {
        return (
          <LinkComponent key={item.key} to={item.to} {...props}>
            {children}
          </LinkComponent>
        );
      }
      return (
        <a key={item.key} href={item.to} {...props}>
          {children}
        </a>
      );
    }
    return (
      <button key={item.key} type="button" {...props}>
        {children}
      </button>
    );
  };

  const renderBarItem = (item: MobileNavItem) =>
    renderNavEl(
      item,
      cn(BAR_ITEM, itemColor(!!item.active)),
      item.onClick,
      <>
        {item.renderIcon({ active: !!item.active, size: 24 })}
        <span className="text-xs mt-1 font-medium">{item.label}</span>
      </>,
    );

  return (
    <div ref={ref} className={cn("md:hidden", className)}>
      <nav className="fixed bottom-0 left-2 right-2 z-50 bottom-nav-safe">
        {/* Hidden, always-expanded copy of the whole pill (items + worst-case
            toolbar) at its natural width, used only to decide whether it fits. */}
        <div ref={measureRef} aria-hidden className="pointer-events-none invisible absolute left-0 top-0">
          <div className={cn(PILL, "w-fit whitespace-nowrap")}>
            {navItems.map(renderBarItem)}
            {measureToolbar ?? toolbar}
          </div>
        </div>

        {/* Available-width reference (capped + centered). The single frosted pill
            sizes to its content within it -- the toolbar stays nested in the same
            pill, with the nav items (or the hamburger) to its left. */}
        <div ref={containerRef} className="max-w-lg mx-auto">
          <div className={cn(PILL, "w-fit max-w-full mx-auto")}>
            {overflow ? (
              <button
                type="button"
                aria-label={menuLabel}
                aria-expanded={menuOpen}
                aria-haspopup="menu"
                onClick={() => setMenuOpen((o) => !o)}
                className={cn(BAR_ITEM, itemColor(navItems.some((i) => i.active)))}
              >
                {menuIcon}
                <span className="text-xs mt-1 font-medium">{menuLabel}</span>
              </button>
            ) : (
              navItems.map(renderBarItem)
            )}
            {toolbar}
          </div>
        </div>
      </nav>

      {/* Frosted menu above the bar; items as inline rows. */}
      {overflow && menuOpen && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setMenuOpen(false)} aria-hidden />
          <div
            ref={menuRef}
            tabIndex={-1}
            className={cn(
              "fixed start-2 z-50 min-w-[12rem] max-w-[16rem] p-2 rounded-2xl flex flex-col gap-1",
              "backdrop-blur-[16px] shadow-lg",
              "bg-[color-mix(in_srgb,var(--color-surface-light)_85%,transparent)]",
              "dark:bg-[color-mix(in_srgb,var(--color-surface-dark)_85%,transparent)]",
              "border border-[var(--color-border-light)] dark:border-[var(--color-border-dark)]",
            )}
            style={{ bottom: "calc(var(--wj-safe-bottom) + 4.75rem)" }}
            role="menu"
          >
            {navItems.map((item) =>
              renderNavEl(
                item,
                cn(MENU_ITEM, menuItemColor(!!item.active)),
                () => {
                  setMenuOpen(false);
                  item.onClick?.();
                },
                <>
                  {item.renderIcon({ active: !!item.active, size: 20 })}
                  <span>{item.label}</span>
                </>,
                "menuitem",
              ),
            )}
          </div>
        </>
      )}
    </div>
  );
});

MobileBottomNav.displayName = "MobileBottomNav";
